        private static Dictionary<double, Dictionary<string, double?>> Table(string key) => key != null && key.StartsWith("DokaFit Prop", StringComparison.Ordinal) ? DokaFitPropCapacities : PropCapacities;
        public static double? GetCapacity(double extension, string key)
        {
            if (key == null) return null;
            return Table(key).TryGetValue(extension, out var row) && row.TryGetValue(key, out var value) ? value : null;
        }
        public static double CapacityAtExtensionMm(double extensionMm, string key, out double lookupMm)
        {
            lookupMm = 0;
            if (double.IsNaN(extensionMm) || double.IsInfinity(extensionMm) || key == null) throw new ArgumentException("Enter a valid prop extension and configuration.");
            var rows = Table(key).Where(r => r.Value.TryGetValue(key, out var v) && v.HasValue && v.Value > 0).OrderBy(r => r.Key).ToList();
            if (rows.Count == 0) throw new ArgumentException("Select a supported prop type and outer tube orientation.");
            double minimum = rows.First().Key * 1000, maximum = rows.Last().Key * 1000;
            const double toleranceMm = 0.0000001; // Arithmetic noise only; not an installation allowance.
            if (extensionMm < minimum - toleranceMm || extensionMm > maximum + toleranceMm)
                throw new ArgumentException($"Prop extension must be within the published table range {minimum:0}–{maximum:0} mm.");
            lookupMm = Math.Ceiling((extensionMm - toleranceMm) / 100) * 100;
            double? capacity = GetCapacity(lookupMm / 1000, key);
            if (!capacity.HasValue || capacity.Value <= 0) throw new ArgumentException("No published capacity for this extension and configuration.");
            return capacity.Value;
        }
